      <h1
          ref={ref}
          className={`text-4xl text-center mb-5 text-yellow-400 ${
            inView ? "opacity-100 translate-y-0" : "opacity-0 translate-y-10"
          }`}
        >
          {title}
        </h1>
      <div className="">Mercury</div>
      <img src={image} alt="" className=' object-contain' />
    </div>
  )
}

export default Mercury
